import{_ as o,c as e,o as a,ag as r}from"./chunks/framework._xRlcm3f.js";const g=JSON.parse('{"title":"语雀网页版配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/custom-yuqueweb.md","filePath":"platforms/custom-yuqueweb.md","lastUpdated":1790228279000}'),d={name:"platforms/custom-yuqueweb.md"};function l(i,t,s,n,c,u){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="语雀网页版配置指南" tabindex="-1">语雀网页版配置指南 <a class="header-anchor" href="#语雀网页版配置指南" aria-label="Permalink to &quot;语雀网页版配置指南&quot;">​</a></h1><p>通过 <strong>Cookie 授权</strong>发布到语雀，<strong>无需专业会员</strong>，使用浏览器登录态即可发布。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可登录的语雀账号（网页版）。</li><li>无需 API Token。</li></ol><h2 id="二、配置" tabindex="-1">二、配置 <a class="header-anchor" href="#二、配置" aria-label="Permalink to &quot;二、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>语雀站点地址，固定为 <code>https://www.yuque.com</code>，通常无需修改</td></tr><tr><td>API地址</td><td>语雀接口地址，与站点地址一致，通常无需修改</td></tr><tr><td>Cookie</td><td>点「去登录」登录语雀 → 关闭登录窗口（关闭时保存登录态）→ 点「自动读取 Cookie」写入本账号；也可展开「手动编辑」直接粘贴</td></tr><tr><td>预览规则</td><td>查看文章链接模板，默认 <code>/{login}/{bookSlug}/{slug}</code>，支持 <code>{login}</code>、<code>{bookSlug}</code>、<code>{slug}</code> 占位符，一般不改</td></tr><tr><td>发布格式</td><td>语雀网页版按 Markdown 提交正文，保持默认的 Markdown</td></tr><tr><td>知识库</td><td>验证通过后选择要发布到的知识库（读取当前登录账号可写的知识库列表）</td></tr><tr><td>图床服务</td><td>默认「当前平台」，图片作为语雀附件上传；也可选「不使用」按原图地址引用（需公网可访问）。语雀网页版不支持 PicGo</td></tr></tbody></table><h2 id="三、验证与发布" tabindex="-1">三、验证与发布 <a class="header-anchor" href="#三、验证与发布" aria-label="Permalink to &quot;三、验证与发布&quot;">​</a></h2><ol><li>点「去登录」→ 打开语雀登录页 → 登录成功 → <strong>关闭登录窗口</strong>（关闭时保存 Cookie）。</li><li>点「自动读取 Cookie」→ 读取到登录态后点「验证」→ 账号状态变为已授权。</li><li>选择知识库后保存配置。</li><li>快速发布 → 选语雀网页版 → 发布。发布后可在「查看文章」打开文章。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>Cookie 读取失败</strong>：确认已登录语雀，关闭登录窗口后点「自动读取 Cookie」重新获取。</li><li><strong>和 API 模式有什么区别</strong>：Cookie 模式无需专业会员，但依赖浏览器登录状态；API 模式更稳但受语雀会员策略限制。</li><li><strong>发布失败但配置能验证</strong>：检查目标知识库写入权限和 Cookie 是否过期，再重新读取 Cookie 后验证。</li><li><strong>文章发布到哪里</strong>：发布到所选知识库下；未选择知识库时不会发布，验证通过后会读取可写知识库列表。</li></ul>',10)])])}const k=o(d,[["render",l]]);export{g as __pageData,k as default};
